package com.gallery.app;

import android.content.*;
import android.database.Cursor;
import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.media.MediaMetadataRetriever;
import android.net.Uri;
import android.os.Build;
import android.provider.MediaStore;
import android.security.keystore.KeyGenParameterSpec;
import android.security.keystore.KeyProperties;
import android.util.Base64;
import com.getcapacitor.*;
import com.getcapacitor.annotation.CapacitorPlugin;
import org.json.*;
import java.io.*;
import java.security.*;
import java.security.spec.*;
import java.util.*;
import javax.crypto.*;
import javax.crypto.spec.*;

/** Private media boundary. Ciphertext and its index live only in app-private files/preferences. */
@CapacitorPlugin(name="SecureFolder")
public class SecureFolderPlugin extends Plugin {
  private static final String PREF="secure_folder_v1", PIN_CREDENTIAL="pin_credential", KEY_ALIAS="gallery_secure_media_v1";
  private boolean authenticated=false;

  private File root(){ File f=new File(getContext().getFilesDir(),"secure-media"); if(!f.exists())f.mkdirs(); return f; }
  private android.content.SharedPreferences prefs(){return getContext().getSharedPreferences(PREF,0);}
  @Override public void load(){clearPreviewFiles();}
  @Override protected void handleOnPause(){authenticated=false;clearPreviewFiles();super.handleOnPause();}
  private JSONArray index(){ try{return new JSONArray(prefs().getString("index","[]"));}catch(Exception e){return new JSONArray();} }
  private JSONArray albumIndex(){try{return new JSONArray(prefs().getString("albums","[]"));}catch(Exception e){return new JSONArray();}}
  private void saveIndex(JSONArray a){prefs().edit().putString("index",a.toString()).commit();}
  private String ensureDefaultAlbum()throws Exception{JSONArray albums=albumIndex();for(int i=0;i<albums.length();i++)if("private-inbox-v1".equals(albums.getJSONObject(i).optString("id")))return "private-inbox-v1";albums.put(new JSONObject().put("id","private-inbox-v1").put("name","Private Media").put("count",0));prefs().edit().putString("albums",albums.toString()).commit();return "private-inbox-v1";}
  private void requireAuth(PluginCall c){if(!authenticated)c.reject("Secure Folder is locked");}
  private SecretKey key() throws Exception {
    KeyStore ks=KeyStore.getInstance("AndroidKeyStore"); ks.load(null);
    if(ks.containsAlias(KEY_ALIAS))return (SecretKey)ks.getKey(KEY_ALIAS,null);
    KeyGenerator kg=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");
    kg.init(new KeyGenParameterSpec.Builder(KEY_ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).setRandomizedEncryptionRequired(true).build());
    return kg.generateKey();
  }
  @PluginMethod public void status(PluginCall c){c.resolve(new JSObject().put("configured",prefs().contains(PIN_CREDENTIAL)).put("authenticated",authenticated));}
  @PluginMethod public void setupPin(PluginCall c){
    String pin=c.getString("pin"); if(pin==null||!pin.matches("[0-9]{4,6}")){c.reject("PIN must contain 4 to 6 digits");return;}
    try{byte[] salt=new byte[16];new SecureRandom().nextBytes(salt);byte[] hash=derive(pin,salt), credential=new byte[salt.length+hash.length];System.arraycopy(salt,0,credential,0,salt.length);System.arraycopy(hash,0,credential,salt.length,hash.length);prefs().edit().putString(PIN_CREDENTIAL,Base64.encodeToString(protect(credential),2)).commit();authenticated=true;c.resolve(new JSObject().put("ok",true));}catch(Exception e){c.reject("Secure PIN setup failed");}
  }
  @PluginMethod public void verifyPin(PluginCall c){
    String pin=c.getString("pin"); if(pin==null||!pin.matches("[0-9]{4,6}")){c.resolve(new JSObject().put("ok",false));return;}
    long until=prefs().getLong("retry_until",0);if(System.currentTimeMillis()<until){authenticated=false;c.resolve(new JSObject().put("ok",false).put("retryAfterMs",until-System.currentTimeMillis()));return;}
    try{byte[] credential=unprotect(Base64.decode(prefs().getString(PIN_CREDENTIAL,""),2)),salt=Arrays.copyOfRange(credential,0,16),expected=Arrays.copyOfRange(credential,16,credential.length); authenticated=MessageDigest.isEqual(expected,derive(pin,salt));if(authenticated)prefs().edit().putInt("failures",0).putLong("retry_until",0).commit();else{int failures=prefs().getInt("failures",0)+1;long delay=failures<5?0:Math.min(3600000L,30000L*(1L<<Math.min(7,failures-5)));prefs().edit().putInt("failures",failures).putLong("retry_until",System.currentTimeMillis()+delay).commit();}c.resolve(new JSObject().put("ok",authenticated).put("retryAfterMs",authenticated?0:Math.max(0,prefs().getLong("retry_until",0)-System.currentTimeMillis())));}catch(Exception e){authenticated=false;c.resolve(new JSObject().put("ok",false));}
  }
  private byte[] derive(String pin,byte[] salt)throws Exception{PBEKeySpec spec=new PBEKeySpec(pin.toCharArray(),salt,310000,256);try{return SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded();}finally{spec.clearPassword();}}
  private byte[] protect(byte[] clear)throws Exception{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key());ByteArrayOutputStream b=new ByteArrayOutputStream();b.write(c.getIV());b.write(c.doFinal(clear));return b.toByteArray();}
  private byte[] unprotect(byte[] blob)throws Exception{byte[] iv=Arrays.copyOfRange(blob,0,12),data=Arrays.copyOfRange(blob,12,blob.length);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,iv));return c.doFinal(data);}
  @PluginMethod public void lock(PluginCall c){authenticated=false;clearPreviewFiles();c.resolve(new JSObject().put("ok",true));}
  @PluginMethod public void albums(PluginCall c){requireAuth(c);if(!authenticated)return;try{JSONArray src=index(), out=new JSONArray(), saved=albumIndex();Map<String,JSONObject> map=new LinkedHashMap<>();for(int i=0;i<saved.length();i++){JSONObject a=saved.getJSONObject(i);a.put("count",0);map.put(a.getString("id"),a);}for(int i=0;i<src.length();i++){JSONObject m=src.getJSONObject(i);String id=m.getString("albumId");JSONObject a=map.get(id);if(a!=null)a.put("count",a.getInt("count")+1);}for(JSONObject a:map.values())out.put(a);c.resolve(new JSObject().put("albums",out));}catch(Exception e){c.reject("Private index is unavailable");}}
  @PluginMethod public void createAlbum(PluginCall c){requireAuth(c);if(!authenticated)return;String name=c.getString("name","").trim();if(name.isEmpty()){c.reject("Album name is required");return;}String id=UUID.randomUUID().toString();try{JSONArray a=albumIndex();JSONObject row=new JSONObject().put("id",id).put("name",name).put("count",0);a.put(row);prefs().edit().putString("albums",a.toString()).commit();c.resolve(new JSObject().put("id",id).put("name",name).put("count",0));}catch(Exception e){c.reject("Could not create private album");}}
  @PluginMethod public void listMedia(PluginCall c){requireAuth(c);if(!authenticated)return;String id=c.getString("albumId");JSONArray out=new JSONArray(), src=index();for(int i=0;i<src.length();i++){JSONObject m=src.optJSONObject(i);if(m!=null&&id.equals(m.optString("albumId")))out.put(m);}c.resolve(new JSObject().put("media",out));}
  @PluginMethod public void importDeviceMedia(PluginCall c){try{String albumId=ensureDefaultAlbum(),mediaId=c.getString("mediaId"),type=c.getString("type");if(mediaId==null||(!"image".equals(type)&&!"video".equals(type)))throw new IllegalArgumentException("Invalid media item");Uri base="video".equals(type)?MediaStore.Video.Media.EXTERNAL_CONTENT_URI:MediaStore.Images.Media.EXTERNAL_CONTENT_URI;Uri uri=Uri.withAppendedPath(base,mediaId);String mime=getContext().getContentResolver().getType(uri);String name=queryName(uri);long date=0,size=0;try(Cursor cur=getContext().getContentResolver().query(uri,new String[]{MediaStore.Images.ImageColumns.DATE_TAKEN,MediaStore.MediaColumns.DATE_ADDED,MediaStore.MediaColumns.SIZE},null,null,null)){if(cur!=null&&cur.moveToFirst()){int d=cur.getColumnIndex(MediaStore.Images.ImageColumns.DATE_TAKEN);int a=cur.getColumnIndex(MediaStore.MediaColumns.DATE_ADDED);int s=cur.getColumnIndex(MediaStore.MediaColumns.SIZE);date=d>=0?cur.getLong(d):0;if(date<=0&&a>=0)date=cur.getLong(a)*1000L;if(s>=0)size=cur.getLong(s);}}try(InputStream in=getContext().getContentResolver().openInputStream(uri)){JSONObject saved=storeEncrypted(in,albumId,name,mime,date,size);c.resolve(new JSObject().put("media",saved).put("sourceId",mediaId).put("sourceType",type));}}catch(Exception e){c.reject("Could not securely copy this media",e);}}
  @PluginMethod public void importLocalMedia(PluginCall c){try{String albumId=ensureDefaultAlbum(),fileName=c.getString("fileName");if(fileName==null||fileName.contains("/")||fileName.contains("\\")||fileName.contains(".."))throw new IllegalArgumentException("Invalid local media");File source=new File(getContext().getFilesDir(),fileName);if(!source.isFile())throw new FileNotFoundException();try(InputStream in=new FileInputStream(source)){JSONObject saved=storeEncrypted(in,albumId,c.getString("name",fileName),c.getString("mimeType","image/jpeg"),c.getLong("dateTaken",System.currentTimeMillis()),source.length());c.resolve(new JSObject().put("media",saved));}}catch(Exception e){c.reject("Could not securely copy this media",e);}}
  private JSONObject storeEncrypted(InputStream source,String albumId,String name,String mime,long date,long size)throws Exception{if(source==null||mime==null||(!mime.startsWith("image/")&&!mime.startsWith("video/")))throw new IOException("Unsupported media type");String albumName="";JSONArray a=albumIndex();for(int i=0;i<a.length();i++)if(albumId.equals(a.optJSONObject(i).optString("id")))albumName=a.optJSONObject(i).optString("name");if(albumName.isEmpty())throw new IOException("Private album not found");String id=UUID.randomUUID().toString();File dest=new File(root(),id+".gcm");try{Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());long copied=0;try(FileOutputStream raw=new FileOutputStream(dest)){DataOutputStream header=new DataOutputStream(raw);header.writeInt(cipher.getIV().length);header.write(cipher.getIV());header.flush();try(CipherOutputStream out=new CipherOutputStream(raw,cipher)){byte[] b=new byte[65536];int n;while((n=source.read(b))!=-1){out.write(b,0,n);copied+=n;}}}try(InputStream verified=decryptStream(dest)){byte[] b=new byte[65536];while(verified.read(b)!=-1){}}if(copied==0)throw new IOException("Empty media file");JSONObject entry=new JSONObject().put("id",id).put("albumId",albumId).put("albumName",albumName).put("file",dest.getName()).put("name",name).put("mimeType",mime).put("type",mime.startsWith("video/")?"video":"image").put("size",copied).put("dateTaken",date>0?date:System.currentTimeMillis());JSONArray idx=index();idx.put(entry);saveIndex(idx);return entry;}catch(Exception e){dest.delete();throw e;}}
  private InputStream decryptStream(File encrypted)throws Exception{DataInputStream in=new DataInputStream(new FileInputStream(encrypted));int n=in.readInt();if(n<12||n>32){in.close();throw new IOException("Invalid encrypted media header");}byte[] iv=new byte[n];in.readFully(iv);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,iv));return new CipherInputStream(in,cipher);}
  @PluginMethod public void openPrivateMedia(PluginCall c){requireAuth(c);if(!authenticated)return;try{JSONObject item=findPrivate(c.getString("id"));File out=new File(previewRoot(),UUID.randomUUID().toString()+extension(item.optString("mimeType")));try(InputStream in=decryptStream(new File(root(),item.getString("file")));OutputStream stream=new FileOutputStream(out)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)stream.write(b,0,n);}c.resolve(new JSObject().put("path",out.getAbsolutePath()).put("mimeType",item.optString("mimeType")));}catch(Exception e){c.reject("Could not open private media",e);}}
  @PluginMethod public void privateThumbnail(PluginCall c){requireAuth(c);if(!authenticated)return;File temp=null;try{JSONObject item=findPrivate(c.getString("id"));temp=new File(previewRoot(),UUID.randomUUID().toString()+extension(item.optString("mimeType")));try(InputStream in=decryptStream(new File(root(),item.getString("file")));OutputStream out=new FileOutputStream(temp)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}Bitmap bitmap;if(item.optString("type").equals("video")){MediaMetadataRetriever r=new MediaMetadataRetriever();r.setDataSource(temp.getAbsolutePath());bitmap=r.getFrameAtTime(0);r.release();}else{BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeFile(temp.getAbsolutePath(),bounds);BitmapFactory.Options opt=new BitmapFactory.Options();opt.inSampleSize=Math.max(1,Math.max(bounds.outWidth,bounds.outHeight)/320);bitmap=BitmapFactory.decodeFile(temp.getAbsolutePath(),opt);}if(bitmap==null)throw new IOException("Thumbnail unavailable");ByteArrayOutputStream bytes=new ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.JPEG,78,bytes);bitmap.recycle();c.resolve(new JSObject().put("thumbnail","data:image/jpeg;base64,"+Base64.encodeToString(bytes.toByteArray(),Base64.NO_WRAP)));}catch(Exception e){c.reject("Could not create private thumbnail",e);}finally{if(temp!=null)temp.delete();}}
  private JSONObject findPrivate(String id)throws Exception{JSONArray a=index();for(int i=0;i<a.length();i++){JSONObject x=a.getJSONObject(i);if(id!=null&&id.equals(x.optString("id")))return x;}throw new FileNotFoundException("Private media not found");}
  private File previewRoot(){File f=new File(getContext().getCacheDir(),"secure-preview");if(!f.exists())f.mkdirs();return f;}
  private void clearPreviewFiles(){File f=new File(getContext().getCacheDir(),"secure-preview");File[] files=f.listFiles();if(files!=null)for(File child:files)child.delete();f.delete();}
  @PluginMethod public void clearPrivatePreview(PluginCall c){clearPreviewFiles();c.resolve(new JSObject().put("ok",true));}
  private String extension(String mime){if(mime==null)return ".bin";if(mime.equals("image/jpeg"))return ".jpg";if(mime.equals("image/png"))return ".png";if(mime.equals("image/webp"))return ".webp";if(mime.equals("video/mp4"))return ".mp4";if(mime.equals("video/webm"))return ".webm";if(mime.equals("video/3gpp"))return ".3gp";return ".media";}
  private String queryName(Uri uri){try(Cursor cur=getContext().getContentResolver().query(uri,new String[]{MediaStore.MediaColumns.DISPLAY_NAME},null,null,null)){if(cur!=null&&cur.moveToFirst())return cur.getString(0);}catch(Exception ignored){}return "Private media";}
  @PluginMethod public void deletePrivateMedia(PluginCall c){requireAuth(c);if(!authenticated)return;String id=c.getString("id");JSONArray src=index(),out=new JSONArray();boolean removed=false;for(int i=0;i<src.length();i++){JSONObject m=src.optJSONObject(i);if(m!=null&&id.equals(m.optString("id"))){new File(root(),m.optString("file")).delete();removed=true;}else out.put(m);}saveIndex(out);c.resolve(new JSObject().put("removed",removed));}
  @PluginMethod public void restoreMedia(PluginCall c){requireAuth(c);if(!authenticated)return;String id=c.getString("id");JSONArray src=index();try{JSONObject item=null;for(int i=0;i<src.length();i++)if(id.equals(src.getJSONObject(i).optString("id")))item=src.getJSONObject(i);if(item==null)throw new FileNotFoundException();File encrypted=new File(root(),item.getString("file"));String mime=item.optString("mimeType","application/octet-stream"),name=item.optString("name","restored-media");String ext="";int dot=name.lastIndexOf('.');if(dot>0)ext=name.substring(dot);String display="Restored_"+System.currentTimeMillis()+ext;android.content.ContentValues values=new android.content.ContentValues();values.put(MediaStore.MediaColumns.DISPLAY_NAME,display);values.put(MediaStore.MediaColumns.MIME_TYPE,mime);if(Build.VERSION.SDK_INT>=29)values.put(MediaStore.MediaColumns.RELATIVE_PATH,"DCIM/Restored");Uri collection=mime.startsWith("video/")?MediaStore.Video.Media.EXTERNAL_CONTENT_URI:MediaStore.Images.Media.EXTERNAL_CONTENT_URI;Uri out=getContext().getContentResolver().insert(collection,values);if(out==null)throw new IOException("Unable to create gallery item");long bytes=0;try(DataInputStream in=new DataInputStream(new FileInputStream(encrypted))){int len=in.readInt();byte[] iv=new byte[len];in.readFully(iv);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,iv));try(InputStream clear=new CipherInputStream(in,cipher);OutputStream target=getContext().getContentResolver().openOutputStream(out,"w")){if(target==null)throw new IOException("Unable to write gallery item");byte[] b=new byte[65536];int n;while((n=clear.read(b))!=-1){target.write(b,0,n);bytes+=n;}}}if(bytes<=0)throw new IOException("Restored item was empty");JSONArray next=new JSONArray();for(int i=0;i<src.length();i++){JSONObject m=src.getJSONObject(i);if(!id.equals(m.optString("id")))next.put(m);}saveIndex(next);encrypted.delete();c.resolve(new JSObject().put("restored",true).put("bytes",bytes));}catch(Exception e){c.reject("Restore failed; the encrypted private copy was kept",e);}}
  @PluginMethod public void changePin(PluginCall c){requireAuth(c);if(!authenticated)return;String current=c.getString("currentPin"),pin=c.getString("newPin");if(pin==null||!pin.matches("[0-9]{4,6}")){c.reject("New PIN must contain 4 to 6 digits");return;}try{byte[] old=unprotect(Base64.decode(prefs().getString(PIN_CREDENTIAL,""),2));if(current==null||!MessageDigest.isEqual(Arrays.copyOfRange(old,16,old.length),derive(current,Arrays.copyOfRange(old,0,16)))){c.reject("Current PIN is incorrect");return;}byte[] s=new byte[16];new SecureRandom().nextBytes(s);byte[] hash=derive(pin,s),credential=new byte[s.length+hash.length];System.arraycopy(s,0,credential,0,s.length);System.arraycopy(hash,0,credential,s.length,hash.length);prefs().edit().putString(PIN_CREDENTIAL,Base64.encodeToString(protect(credential),2)).putInt("failures",0).putLong("retry_until",0).commit();c.resolve(new JSObject().put("ok",true));}catch(Exception e){c.reject("PIN could not be updated");}}
}
